using _2026_web_api_01.Infrastructure.Data;
using _2026_web_api_01.Infrastructure.Repositories;
using _2026_web_api_01.Services.Implementations;
using _2026_web_api_01.Services.Interfaces;

var builder = WebApplication.CreateBuilder(args);

// ---------------------------------------------------------------------------
// Register application services (Clean Architecture dependency injection)
// ---------------------------------------------------------------------------

// Infrastructure layer
builder.Services.AddSingleton<DapperContext>();
builder.Services.AddScoped<IProductRepository, ProductRepository>();
builder.Services.AddScoped<ICategoryRepository, CategoryRepository>();
builder.Services.AddScoped<IInformationRepository, InformationRepository>();

// Application / Business layer
builder.Services.AddScoped<IProductService, ProductService>();
builder.Services.AddScoped<ICategoryService, CategoryService>();
builder.Services.AddScoped<IInformationService, InformationService>();

// ASP.NET Core built-in services
builder.Services.AddControllers();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new()
    {
        Title = "2026 Web API 01",
        Version = "v1",
        Description = "Production-ready Web API built with Clean Architecture, Dapper, and Stored Procedures."
    });
});

var app = builder.Build();

// ---------------------------------------------------------------------------
// Middleware pipeline
// ---------------------------------------------------------------------------

if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseHttpsRedirection();
app.UseAuthorization();
app.MapControllers();

app.Run();
