-- API_InfoCategory_GetAll: Lấy tất cả danh mục (sắp xếp theo SortOrder, sau đó theo CategoryName)
Create Procedure API_InfoCategory_GetAll
As
Begin
    Set NoCount On;

    Select
        CategoryId,
        CategoryName,
        Description,
        SortOrder,
        IsActive,
        CreatedAt,
        UpdatedAt
    From INFO_Category
    Where IsActive = 1
    Order By SortOrder Asc, CategoryName Asc;
End
