using Microsoft.AspNetCore.Mvc;
using _2026_web_api_01.Models.Requests;
using _2026_web_api_01.Services.Interfaces;

namespace _2026_web_api_01.API.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class ProductController : ControllerBase
{
    private readonly IProductService _productService;

    public ProductController(IProductService productService)
    {
        _productService = productService;
    }

    /// <summary>
    /// GET /api/product/{id}
    /// Retrieves a product by its identifier.
    /// </summary>
    /// <param name="id">The product ID.</param>
    /// <returns>200 OK with the product DTO, or 404 Not Found.</returns>
    [HttpGet("{id:int}")]
    public async Task<IActionResult> GetById(int id)
    {
        var product = await _productService.GetProductByIdAsync(id);

        if (product is null)
        {
            return NotFound(new { Message = $"Product with ID {id} was not found." });
        }

        return Ok(product);
    }

    /// <summary>
    /// POST /api/product
    /// Creates a new product.
    /// </summary>
    /// <param name="request">The validated creation payload.</param>
    /// <returns>201 Created with the created product DTO, or 400 Bad Request on validation failure.</returns>
    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateProductRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        var createdProduct = await _productService.CreateProductAsync(request);

        return CreatedAtAction(nameof(GetById), new { id = createdProduct.Id }, createdProduct);
    }
}
```

