using System.Data;
using Dapper;
using _2026_web_api_01.Infrastructure.Data;
using _2026_web_api_01.Infrastructure.Repositories;
using _2026_web_api_01.Models.Entities;

namespace _2026_web_api_01.Infrastructure.Repositories;

/// <summary>
/// Dapper-based implementation of <see cref="IProductRepository"/>.
/// All database access is performed via stored procedures with
/// <see cref="DynamicParameters"/> to prevent SQL injection.
/// </summary>
public sealed class ProductRepository : IProductRepository
{
    private readonly DapperContext _context;

    public ProductRepository(DapperContext context)
    {
        _context = context;
    }

    /// <inheritdoc />
    public async Task<ProductEntity?> GetByIdAsync(int id)
    {
        using var connection = _context.CreateConnection();

        var parameters = new DynamicParameters();
        parameters.Add("@Id", id);

        var product = await connection.QuerySingleOrDefaultAsync<ProductEntity>(
            sql: "sp_GetProductById",
            param: parameters,
            commandType: CommandType.StoredProcedure
        );

        return product;
    }

    /// <inheritdoc />
    public async Task<ProductEntity> CreateAsync(ProductEntity product)
    {
        using var connection = _context.CreateConnection();

        var parameters = new DynamicParameters();
        parameters.Add("@Name", product.Name);
        parameters.Add("@Description", product.Description);
        parameters.Add("@Price", product.Price);
        parameters.Add("@StockQuantity", product.StockQuantity);

        // The stored procedure returns the newly inserted row including its generated Id.
        var createdProduct = await connection.QuerySingleAsync<ProductEntity>(
            sql: "sp_CreateProduct",
            param: parameters,
            commandType: CommandType.StoredProcedure
        );

        return createdProduct;
    }
}
